{
    glm::vec3 position, velocity, acceleration, force;
    float density;
    float pressure;
    uint16_t hash;
};

glm::ivec3 getCell(Particle *p, float h) {
    return glm::ivec3(
        static_cast<int>(std::floor(p->position.x / h)),
        static_cast<int>(std::floor(p->position.y / h)),
        static_cast<int>(std::floor(p->position.z / h))
    );
}

